sys_script_include.script:
// Script Include: ServicoEntity
// Camada: DOMÍNIO — value object / referência do agregado Serviço (área corporal, duração, preço).
// client_callable = FALSE (uso apenas server-side)
var ServicoEntity = Class.create();
ServicoEntity.prototype = {
    initialize: function(gr) {
        // gr: GlideRecord de x_espaco_servico (opcional)
        this.gr = gr || null;
    },

    type: 'ServicoEntity'
};
